apiVersion: kustomize.config.k8s.io/v1beta1
kind: Kustomization
namespace: {{namespace}}
resources:
  - {{base_path}}
namePrefix: {{overlay_env}}-
commonLabels:
  env: {{overlay_env}}
images:
  - name: {{image_name}}
    newTag: {{new_tag}}
patches:
  - target:
      kind: Deployment
      name: {{target_deployment}}
    patch: |-
      - op: replace
        path: /spec/replicas
        value: {{replica_count}}
